# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs, factor=3):
    return [v * factor for v in xs]

# region: fold
def fold(xs):
    d = {}
    for v in xs[:-1]:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: sift
def sift(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return sift(fold(shape(digest(intake(raw)))))

